def render_beams(H,W, objects):
    # objects = [(r,c,color,kind/name)] with color 0 for blank cross
    orig=[[0]*W for _ in range(H)]
    arms_by={}
    for k,(r,c,v) in enumerate(objects):
        arms={(r+dr,c+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)] if 0<=r+dr<H and 0<=c+dc<W}
        arms_by[k]=arms
        if v: orig[r][c]=v
        for rr,cc in arms: orig[rr][cc]=3
    horiz=[[None]*W for _ in range(H)]; vert=[[None]*W for _ in range(H)]
    dirs=[(0,1),(0,-1),(1,0),(-1,0)]
    for k,(r,c,v) in enumerate(objects):
        # generate horizontal and vertical rays, stop on arms belonging to another object; preserve but pass own arms
        for axis, dest, raydirs in [('h',horiz,[(0,1),(0,-1)]),('v',vert,[(1,0),(-1,0)])]:
            dest[r][c]=v
            for dr,dc in raydirs:
                rr,cc=r+dr,c+dc
                while 0<=rr<H and 0<=cc<W:
                    blocker=any((rr,cc) in a for kk,a in arms_by.items() if kk!=k)
                    if blocker: break
                    dest[rr][cc]=v
                    rr+=dr; cc+=dc
    out=[row[:] for row in orig]
    for r in range(H):
        for c in range(W):
            if orig[r][c]==0 and horiz[r][c] is not None: out[r][c]=horiz[r][c]
    for r in range(H):
        for c in range(W):
            if orig[r][c]==0 and vert[r][c] is not None: out[r][c]=vert[r][c]
    return out
